+test("RF-006: descuento global sobre el total, con IVA y neto recalculados", () => {
+  const items = [
+    { cantidad: 2, precioUnitarioCentavos: 5000 },
+    { cantidad: 1, precioUnitarioCentavos: 1050 },
+  ];
+  // 11050 - round(1105) = 9945; IVA round(9945 * 0,13) = 1293; neto 8652
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), { totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652 });
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 0 }), calcularFactura(items));
+  assert.equal(calcularFactura(items, { descuentoGlobal: 100 }).totalCentavos, 0);
+  // redondeo al centavo: 1005 * 15 % = 150,75 -> 151
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1005 }], { descuentoGlobal: 15 }).totalCentavos, 854);
+  for (const malo of [-1, 101, 10.5, "10", NaN])
+    assert.throws(() => calcularFactura(items, { descuentoGlobal: malo }), RangeError);
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items, descuentoGlobal: 10 });
+  assert.equal(f.totalCentavos, 9945);
+});
